INSERT INTO contract_template_versions(id,tenant_id,template_id,version_no,body_template,variable_schema,process_config,status,published_at) VALUES('5ac03597-d999-514b-ac65-ebd65e513f2f','00000000-0000-0000-0000-000000000001','7cbf4d31-37a4-5f51-9f6a-cdb9ccbc6bbe',1,'قرارداد اجاره
نسخه نمایشی برای تدوین؛ این متن تصویب حقوقی نشده است.
۱. طرفین و موضوع: این سند با عنوان «{{title}}» بین {{unit}} و {{party}} برای واگذاری منفعت مورد اجاره در مدت معین تنظیم می‌شود. نماینده پیگیری: {{owner}}.
۲. دامنه و تعهدات: مشخصات مورد اجاره، محل، ودیعه، مسئولیت نگهداری و شرایط تحویل و تخلیه در صورت‌جلسه پیوست درج می‌شود. خدمات انتخاب‌شده: {{services}}. موارد نامشخص باید پیش از امضا تکمیل شوند.
۳. مدت: دوره اجرای قرارداد از {{start}} تا {{end}} است؛ تغییر یا تمدید فقط با توافق مکتوب ثبت می‌شود.
۴. مبلغ و پرداخت: مبلغ توافق‌شده {{amount}} ریال است. زمان و شروط پرداخت، مالیات و اسناد لازم در پیوست مالی درج و تأیید می‌شود. هیچ نرخ یا تخفیف خودکار مفروض نیست.
۵. پذیرش و سطح خدمت: معیارهای پذیرش و مسئول هر تحویل صریحاً تعیین می‌شوند. SLA خدمت و SLA مرحله بررسی قرارداد مستقل‌اند؛ تعهد نامعلوم پیش‌فرض قطعی ندارد.
۶. محرمانگی و مالکیت: هر طرف اطلاعات طرف دیگر را در حدود موضوع قرارداد استفاده می‌کند. حقوق مالکیت، مجوزهای لازم و اقدامات حفاظت داده پیش از امضا تعیین می‌شوند.
۷. تغییر، خاتمه و اختلاف: تغییر دامنه، آثار مالی و زمانی، مهلت رفع نقض و روش حل اختلاف باید با تأیید طرفین ثبت شود. اسناد و پیوست‌های دارای نسخه جزء سوابق قرارداد هستند.
۸. امضا و پیوست‌ها: امضای نمایندگان مجاز پس از تکمیل بازبینی‌ها و ثبت نسخه نهایی انجام می‌شود. این پیش‌نویس برای نمایش سامانه است و جایگزین متن تأییدشده سازمان نیست.','{"fields":[{"key":"title","label":"title","required":true},{"key":"party","label":"party","required":true},{"key":"start","label":"start","required":false},{"key":"end","label":"end","required":false},{"key":"amount","label":"amount","required":false},{"key":"services","label":"services","required":false},{"key":"unit","label":"unit","required":false},{"key":"owner","label":"owner","required":false}]}','{"stages":[{"id":"legal","name":"بررسی حقوقی","role":"legal","slaDays":2,"required":true,"enabled":true},{"id":"finance","name":"بررسی مالی","role":"finance","slaDays":2,"required":true,"enabled":true},{"id":"management","name":"تأیید مدیریت","role":"management","slaDays":1,"required":true,"enabled":true},{"id":"sign","name":"امضای مجاز","role":"signatory","slaDays":3,"required":true,"enabled":true}],"serviceCodes":[],"revenueModels":["fixed"]}','published','2026-09-30T00:00:00Z') ON CONFLICT(tenant_id,template_id,version_no) DO NOTHING;
